import numpy as np
# invalid input: a ratio of specific heats of one is not greater than one and must raise ValueError
rho = np.array([1.2])
e = np.array([2.0e5])
gamma = 1.0
pi_ = 0.0
def _catches_value_error(fn):
    try:
        fn()
    except ValueError:
        return np.array([1.0])
    return np.array([0.0])
assert np.allclose(_catches_value_error(lambda: stiffened_gas_pressure(rho, e, gamma, pi_)), target)

